function toPosixSeparators(query: string): string {
	if (!DRIVE_PREFIX_REGEX.test(query) && !query.startsWith(WINDOWS_SEPARATOR)) return query;

	return query.split(WINDOWS_SEPARATOR).join(PATH_SEPARATOR);
}

binaryConvert = (num: number): string => {
  let binary = ''

  while (num !== 0) {
    binary = (num % 2) + binary
    num = Math.floor(num / 2)
  }

  return binary
}

function trimCodePadding(code: string): string {
	return code.replace(TRIM_LEADING_PADDING_REGEX, '').replace(TRIM_TRAILING_PADDING_REGEX, '');
}

export function normalizeModelName(modelName: string): string {
	const trimmed = modelName.trim();

	if (!trimmed) {
		return '';
	}

	const segments = trimmed.split(FILE_PATH_SEPARATOR_REGEX);

	// If we have exactly 2 segments (one slash), treat it as Hugging Face repo format
	// and preserve the full "org/model" format
	if (segments.length === 2) {
		const [org, model] = segments;
		const trimmedOrg = org?.trim();
		const trimmedModel = model?.trim();

		if (trimmedOrg && trimmedModel) {
			return `${trimmedOrg}/${trimmedModel}`;
		}
	}

	// For other cases (no slash, or multiple slashes), extract just the filename
	const candidate = segments.pop();
	const normalized = candidate?.trim();

	return normalized && normalized.length > 0 ? normalized : trimmed;
}

function escapeCode(code: string): string {
	return code.replace(AMPERSAND_REGEX, '&amp;').replace(LT_REGEX, '&lt;').replace(GT_REGEX, '&gt;');
}

export function range(start: number, end?: number, step = 1): number[] {
  if (end == null) {
    end = start;
    start = 0;
  }

  if (!Number.isInteger(step) || step === 0) {
    throw new Error(`The step value must be a non-zero integer.`);
  }

  const length = Math.max(Math.ceil((end - start) / step), 0);
  const result = new Array<number>(length);

  for (let i = 0; i < length; i++) {
    result[i] = start + i * step;
  }

  return result;
}

function dedentImpl(text: string): string {
  text = text.replace(/\r\n/g, '\n');
  const lines = text.split('\n');

  if (lines.length > 0 && lines[0].trim() === '') {
    lines.shift();
  }

  if (lines.length > 0 && lines[lines.length - 1].trim() === '') {
    lines.pop();
  }

  let commonIndent = Infinity;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];

    if (line.trim() === '') {
      continue;
    }

    let indent = 0;
    while (indent < line.length && (line[indent] === ' ' || line[indent] === '\t')) {
      indent++;
    }

    if (indent < commonIndent) {
      commonIndent = indent;
    }
  }

  if (commonIndent === Infinity) {
    return '';
  }

  for (let i = 0; i < lines.length; i++) {
    if (lines[i].trim() === '') {
      lines[i] = '';
    } else {
      lines[i] = lines[i].slice(commonIndent);
    }
  }

  return lines.join('\n');
}

export function normalizeResourceUri(uri: string): string {
	const schemeEnd = uri.indexOf(URI_SCHEME_SEPARATOR);

	if (schemeEnd === -1) return uri;

	const scheme = uri.substring(0, schemeEnd);
	const rest = uri
		.substring(schemeEnd + URI_SCHEME_SEPARATOR.length)
		.replace(LEADING_SLASHES_REGEX, '');

	return `${scheme}${URI_SCHEME_SEPARATOR}${rest}`;
}

hammingDistance = (str1: string, str2: string) => {
  if (str1.length !== str2.length)
    throw new Error('Strings must of the same length.')

  let dist = 0

  for (let i = 0; i < str1.length; i++) if (str1[i] !== str2[i]) dist++

  return dist
}

export function lastPathSegment(p: string): string {
	const trimmed = p.replace(TRAILING_SLASHES_REGEX, '');
	const idx = trimmed.lastIndexOf(PATH_SEPARATOR);

	return idx === -1 ? trimmed : trimmed.slice(idx + 1);
}

export function isValidModelName(modelName: string): boolean {
	return normalizeModelName(modelName).length > 0;
}

export function buildCaseInsensitiveGlob(query: string): string {
	let out = GLOB_WILDCARD;

	for (const c of query) {
		const lo = c.toLowerCase();
		const up = c.toUpperCase();

		if (lo !== up) out += GLOB_RANGE_OPEN + lo + up + GLOB_RANGE_CLOSE;
		// glob metacharacters are escaped into a literal character class so a
		// query like "a*b" matches a literal '*' instead of becoming "ab"
		else if (GLOB_SPECIAL_CHARS.includes(c)) out += GLOB_RANGE_OPEN + c + GLOB_RANGE_CLOSE;
		else out += c;
	}

	return out + GLOB_WILDCARD;
}

export function addBinary(
  firstBinaryNo: string,
  secondBinaryNo: string
): string {
  let lengthOfFirstNumber: number = firstBinaryNo.length - 1
  let lengthOfSecondNumber: number = secondBinaryNo.length - 1
  const solution: string[] = []
  let carry: number = 0

  while (lengthOfFirstNumber >= 0 || lengthOfSecondNumber >= 0) {
    let sum: number = carry
    if (lengthOfFirstNumber >= 0)
      sum += parseInt(firstBinaryNo.charAt(lengthOfFirstNumber))
    if (lengthOfSecondNumber >= 0)
      sum += parseInt(secondBinaryNo.charAt(lengthOfSecondNumber))
    solution.push((sum % 2).toString())
    carry = Math.floor(sum / 2)
    lengthOfFirstNumber--
    lengthOfSecondNumber--
  }

  if (carry !== 0) solution.push(carry.toString())

  return solution.reverse().join('')
}

